package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import java.util.Date;
import java.util.Iterator;
import java.util.List;
import java.util.TimeZone;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.event.SeriesChangeEvent;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;

/**
 * Unit tests for TimeSeries.createCopy(int start, int end)
 */
public class TimeSeries_createCopy_TriageGen2Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartLessThanZero() throws CloneNotSupportedException {
        series.createCopy(-1, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyEndLessThanStart() throws CloneNotSupportedException {
        series.add(new SecondDataItem(new Date(), 1.0));
        series.createCopy(1, 0);
    }

    @Test
    public void testCreateCopyEmptySeries() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, 0);
        assertNotNull(copy);
        assertEquals(0, copy.getItemCount());
        assertNotSame(series, copy);
    }

    @Test
    public void testCreateCopyValidRange() throws CloneNotSupportedException {
        series.add(new SecondDataItem(new Date(1000), 10.0)); // index 0
        series.add(new SecondDataItem(new Date(2000), 20.0)); // index 1
        series.add(new SecondDataItem(new Date(3000), 30.0)); // index 2

        // Test copying a subset
        TimeSeries copy = series.createCopy(0, 1);

        assertEquals(2, copy.getItemCount());
        assertEquals(10.0, copy.getValue(0).doubleValue(), 0.001);
        assertEquals(20.0, copy.getValue(1).doubleValue(), 0.001);

        // Ensure it is a deep copy of items
        assertNotSame(series.getDataItem(0), copy.getDataItem(0));
    }

    @Test
    public void testCreateCopySingleItem() throws CloneNotSupportedException {
        series.add(new SecondDataItem(new Date(), 5.0));
        TimeSeries copy = series.createCopy(0, 0);
        assertEquals(1, copy.getItemCount());
        assertEquals(5.0, copy.getValue(0).doubleValue(), 0.001);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testCreateCopyIndexOutOfBounds() throws CloneNotSupportedException {
        series.add(new SecondDataItem(new Date(), 1.0));
        // index 1 does not exist
        series.createCopy(0, 1);
    }

    /**
     * Inner class to facilitate testing with concrete DataItems
     */
    private static class SecondDataItem extends TimeSeriesDataItem {
        private final Date period;
        private final double value;

        public SecondDataItem(Date period, double value) {
            super(new org.jfree.data.time.Second(period));
            this.period = period;
            this.value = value;
        }

        @Override
        public Object clone() throws CloneNotSupportedException {
            SecondDataItem clone = (SecondDataItem) super.clone();
            // Ensure date is cloned if necessary, though for this test simple clone is fine
            return clone;
        }

        @Override
        public double getValue() {
            return value;
        }
    }
}
